L["Opacity"] = "Opacità"
L["How opaque the icons are. A buff about to expire can fade further; see the Expiring page."] = "Quanto sono opache le icone. Un potenziamento in scadenza può sbiadire ancora di più; vedi la pagina Scadenza."
L["Layout"] = "Disposizione"
L["How several missing buffs sit side by side. Overlapped lets each icon cover the edge of the last."] = "Come stanno affiancati più potenziamenti mancanti. «Sovrapposte» fa coprire a ogni icona il bordo della precedente."
L["Spacing"] = "Spaziatura"
L["The gap between icons, in pixels."] = "Lo spazio tra le icone, in pixel."
